export function OneTapLogo({
  variant = "horizontal",
  className = "",
  size,
  title = "OneTap Reality",
  ...props
}: OneTapLogoProps) {
  if (variant === "mark") {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 512 512"
        fill="currentColor"
        width={size ?? "1em"}
        height={size ?? "1em"}
        className={className}
        aria-label={title}
        role="img"
        {...props}
      >
        <title>{title}</title>
        <path fillRule="evenodd" clipRule="evenodd" d={ONETAP_MARK_PATH} />
      </svg>
    );
  }

  if (variant === "lockup") {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 600 538"
        fill="currentColor"
        width={size ?? "100%"}
        height={size ?? "auto"}
        className={className}
        aria-label={title}
        role="img"
        {...props}
      >
        <title>{title}</title>
        <path fillRule="evenodd" clipRule="evenodd" d={ONETAP_LOCKUP_PATH} />
      </svg>
    );
  }

  // Horizontal lockup (Icon Mark on left + clean typography on right)
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 280 64"
      fill="none"
      width={size ?? "auto"}
      height={size ?? "2rem"}
      className={className}
      aria-label={title}
      role="img"
      {...props}
    >
      <title>{title}</title>
      <g transform="translate(0, 0) scale(0.125)">
        <path
          fillRule="evenodd"
          clipRule="evenodd"
          d={ONETAP_MARK_PATH}
          fill="currentColor"
        />
      </g>
      <text
        x="76"
        y="36"
        fontFamily="system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
        fontSize="25"
        fontWeight="800"
        letterSpacing="-0.6px"
        fill="currentColor"
      >
        OneTap
      </text>
      <text
        x="78"
        y="52"
        fontFamily="system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif"
        fontSize="9.5"
        fontWeight="700"
        letterSpacing="3.2px"
        fill="currentColor"
        opacity="0.72"
      >
        REALITY
      </text>
    </svg>
  );
}

export function OneTapMark({
  size = 24,
  className = "",
  title = "OneTap Reality",
  ...props
}: Omit<OneTapLogoProps, "variant">) {
  return (
    <OneTapLogo
      variant="mark"
      size={size}
      className={className}
      title={title}
      {...props}
    />
  );
}
